import json
import sys
import time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from email.utils import parsedate_to_datetime
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)
REGIONS = ('north', 'south', 'east', 'west')
token = None
stats = {'token_refreshes': 0, 'rate_limits': 0, 'network_retries': 0}

def delay_from(header):
    if header is None:
        return 1.0
    try:
        return max(0.0, float(header))
    except ValueError:
        return max(0.0, (parsedate_to_datetime(header) - datetime.now(timezone.utc)).total_seconds())

def request(path, auth=True, method='GET'):
    global token
    for attempt in range(100):
        if auth and token is None:
            token = [REDACTED_SECRET]'/token', auth=False, method='POST')['token']
            stats['token_refreshes'] += 1
        headers = {'Authorization': 'Bearer ' + token} if auth else {}
        req = Request(BASE + path, headers=headers, method=method)
        try:
            with urlopen(req, timeout=20) as response:
                return json.load(response)
        except HTTPError as error:
            if error.code == 401 and auth:
                token = None
                continue
            if error.code == 429:
                stats['rate_limits'] += 1
                time.sleep(delay_from(error.headers.get('Retry-After')))
                continue
            if 500 <= error.code < 600:
                stats['network_retries'] += 1
                time.sleep(min(2 ** min(attempt, 4), 15))
                continue
            raise RuntimeError(f'{path}: HTTP {error.code}') from error
        except (URLError, TimeoutError) as error:
            stats['network_retries'] += 1
            time.sleep(min(2 ** min(attempt, 4), 15))
    raise RuntimeError(f'{path}: exhausted retries')

orders = {}
duplicates = 0
page_path = '/orders?page=1'
expected_page = 1
expected_total = None
while page_path:
    page = request(page_path)
    assert page['page'] == expected_page, (page_path, page['page'])
    if expected_total is None:
        expected_total = page['total_pages']
    assert page['total_pages'] == expected_total
    assert isinstance(page['items'], list)
    for order in page['items']:
        order_id = order['id']
        if order_id in orders:
            assert orders[order_id] == order, f'conflicting duplicate {order_id}'
            duplicates += 1
        else:
            orders[order_id] = order
    page_path = page['next']
    expected_page += 1
    if expected_page > expected_total + 1:
        raise RuntimeError('pagination exceeded declared total')
    if (expected_page - 1) % 10 == 0 or page_path is None:
        print(f'Fetched {expected_page - 1}/{expected_total} pages; unique orders={len(orders)}; duplicates={duplicates}', flush=True)
assert expected_page - 1 == expected_total

customers = {}
by_region = {region: 0 for region in REGIONS}
qualifying_ids = set()
for order in orders.values():
    if order['status'] "'!= '"'shipped':
        continue
    stamp = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00'))
    assert stamp.tzinfo is not None
    if not START <= stamp.astimezone(timezone.utc) < END:
        continue
    customer_id = order['customer_id']
    if customer_id not in customers:
        customer = request('/customers/' + customer_id)
        assert customer['id'] == customer_id
        assert customer['region'] in REGIONS
        assert isinstance(customer['discount_pct'], int) and 0 <= customer['discount_pct'] <= 100
        customers[customer_id] = customer
    customer = customers[customer_id]
    amount = order['amount_cents']
    assert isinstance(amount, int) and amount >= 0
    discounted = int((Decimal(amount) * (Decimal(100 - customer['discount_pct']) / 100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    by_region[customer['region']] += discounted
    assert order['id'] not in qualifying_ids
    qualifying_ids.add(order['id'])

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying_ids),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
assert sum(result['by_region'].values()) == result['total_cents']
with open('/workspace/result.json', 'w') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
print(json.dumps({'result': result, 'unique_orders': len(orders), 'customers_fetched': len(customers), 'stats': stats}), flush=True)
